use std::fs;

use assert_cmd::cargo::cargo_bin_cmd;
use tempfile::NamedTempFile;
use tempfile::TempDir;

use pickle_fuzzer::{Generator, Version};

#[test]
fn test_generate_all_protocol_versions() {
    for version_num in 0..=5 {
        let version = Version::try_from(version_num).unwrap();
        let mut gen = Generator::new(version);
        let result = gen.generate();
        assert!(
            result.is_ok(),
            "Failed to generate for version {}",
            version_num
        );
        let pickle = result.unwrap();
        assert!(
            !pickle.is_empty(),
            "Empty pickle for version {}",
            version_num
        );
        // All pickles should end with STOP opcode (0x2e or '.')
        assert_eq!(
            pickle[pickle.len() - 1],
            b'.',
            "Missing STOP opcode for version {}",
            version_num
        );
    }
}

#[test]
fn test_deterministic_generation_with_seed() {
    let seed = 42;
    let mut gen1 = Generator::new(Version::V3).with_seed(seed);
    let mut gen2 = Generator::new(Version::V3).with_seed(seed);

    let pickle1 = gen1.generate().unwrap();
    let pickle2 = gen2.generate().unwrap();

    assert_eq!(
        pickle1, pickle2,
        "Same seed should produce identical pickles"
    );
}

#[test]
fn test_repeated_generation_with_same_seed_on_one_generator_is_deterministic() {
    let mut gen = Generator::new(Version::V3).with_seed(42);

    let pickle1 = gen.generate().unwrap();
    let pickle2 = gen.generate().unwrap();

    assert_eq!(pickle1, pickle2);
}

#[test]
fn test_repeated_generate_from_arbitrary_is_deterministic() {
    let mut gen = Generator::new(Version::V3);

    let pickle1 = gen.generate_from_arbitrary(b"same_input").unwrap();
    let pickle2 = gen.generate_from_arbitrary(b"same_input").unwrap();

    assert_eq!(pickle1, pickle2);
}

#[test]
fn test_different_seeds_produce_different_pickles() {
    let mut gen1 = Generator::new(Version::V3).with_seed(1);
    let mut gen2 = Generator::new(Version::V3).with_seed(2);

    let pickle1 = gen1.generate().unwrap();
    let pickle2 = gen2.generate().unwrap();

    assert_ne!(
        pickle1, pickle2,
        "Different seeds should produce different pickles"
    );
}

#[test]
fn test_opcode_range_configuration() {
    let mut gen = Generator::new(Version::V3)
        .with_min_opcodes(10)
        .with_max_opcodes(20);

    let result = gen.generate();
    assert!(result.is_ok());

    let gen = Generator::new(Version::V3)
        .with_min_opcodes(20)
        .with_max_opcodes(10);
    assert_eq!(gen.min_opcodes, 10);
    assert_eq!(gen.max_opcodes, 10);

    let gen = Generator::new(Version::V3)
        .with_max_opcodes(10)
        .with_min_opcodes(20);
    assert_eq!(gen.min_opcodes, 20);
    assert_eq!(gen.max_opcodes, 20);

    let gen = Generator::new(Version::V3).with_opcode_range(20, 10);
    assert_eq!(gen.min_opcodes, 10);
    assert_eq!(gen.max_opcodes, 20);
}

#[test]
fn test_reset_clears_state() {
    let mut gen = Generator::new(Version::V3);
    gen.generate().unwrap();

    let output_before = gen.output.len();
    assert!(output_before > 0);

    gen.reset();
    assert_eq!(gen.output.len(), 0, "Reset should clear output");
}

#[test]
fn test_builder_pattern() {
    let mut gen = Generator::new(Version::V4)
        .with_seed(123)
        .with_buffer_size(4096)
        .with_opcode_range(50, 100);

    let result = gen.generate();
    assert!(result.is_ok());
}

#[test]
fn test_generate_with_buffer_size_respects_limit() {
    let mut gen = Generator::new(Version::V3)
        .with_seed(123)
        .with_buffer_size(64);
    let pickle = gen.generate().unwrap();

    assert!(pickle.len() <= 64);
    assert_eq!(pickle[pickle.len() - 1], b'.');
}

#[test]
fn test_impossible_total_opcode_budget_errors() {
    let mut gen = Generator::new(Version::V2).with_opcode_range(0, 0);
    let err = gen.generate().unwrap_err().to_string();

    assert!(err.contains("cannot fit a valid protocol 2 pickle"));
}

#[test]
fn test_protocol_v0_generates_ascii() {
    let mut gen = Generator::new(Version::V0).with_seed(999);
    let pickle = gen.generate().unwrap();

    // Protocol 0 should not have PROTO opcode
    assert_ne!(
        pickle[0], 0x80,
        "Protocol 0 should not start with PROTO opcode"
    );
}

#[test]
#[cfg_attr(tarpaulin, ignore)]
fn test_protocol_v2_and_above_have_proto() {
    for version_num in 2..=5 {
        let version = Version::try_from(version_num).unwrap();
        let mut gen = Generator::new(version).with_seed(123);
        let pickle = gen.generate().unwrap();

        // Protocol 2+ should start with PROTO opcode (0x80)
        assert_eq!(
            pickle[0], 0x80,
            "Protocol {} should start with PROTO opcode",
            version_num
        );
        assert_eq!(
            pickle[1], version_num as u8,
            "Protocol byte should match version"
        );
    }
}

#[test]
fn test_cli_single_file_generation() {
    let temp_file = NamedTempFile::new().expect("failed to create temp file");
    let temp_path = temp_file.path().to_str().unwrap();

    cargo_bin_cmd!("pickle-fuzzer")
        .arg(temp_path)
        .assert()
        .success();

    assert!(fs::metadata(temp_path).is_ok(), "output file not created");

    let contents = fs::read(temp_path).expect("failed to read output file");
    assert!(!contents.is_empty(), "output file is empty");
    assert_eq!(contents[contents.len() - 1], b'.', "missing STOP opcode");
}

#[test]
fn test_cli_with_protocol_flag() {
    let temp_file = NamedTempFile::new().expect("failed to create temp file");
    let temp_path = temp_file.path().to_str().unwrap();

    cargo_bin_cmd!("pickle-fuzzer")
        .args(["--protocol", "4", temp_path])
        .assert()
        .success();

    let contents = fs::read(temp_path).expect("failed to read output file");
    assert_eq!(contents[0], 0x80, "should start with PROTO opcode");
    assert_eq!(contents[1], 4, "should be protocol 4");
}

#[test]
fn test_cli_with_seed_produces_deterministic_output() {
    let temp_file1 = NamedTempFile::new().expect("failed to create temp file 1");
    let temp_file2 = NamedTempFile::new().expect("failed to create temp file 2");
    let temp_path1 = temp_file1.path().to_str().unwrap();
    let temp_path2 = temp_file2.path().to_str().unwrap();

    // generate with same seed twice
    cargo_bin_cmd!("pickle-fuzzer")
        .args(["--seed", "42", temp_path1])
        .assert()
        .success();

    cargo_bin_cmd!("pickle-fuzzer")
        .args(["--seed", "42", temp_path2])
        .assert()
        .success();

    let contents1 = fs::read(temp_path1).expect("failed to read file 1");
    let contents2 = fs::read(temp_path2).expect("failed to read file 2");

    assert_eq!(
        contents1, contents2,
        "same seed should produce identical output"
    );
}

#[test]
fn test_cli_batch_mode() {
    let temp_dir = TempDir::new().expect("failed to create temp dir");
    let temp_path = temp_dir.path().to_str().unwrap();

    cargo_bin_cmd!("pickle-fuzzer")
        .args(["--dir", temp_path, "--samples", "5"])
        .assert()
        .success();

    // check that files were created
    let entries = fs::read_dir(temp_path).expect("failed to read dir");
    let count = entries.count();
    assert_eq!(count, 5, "should create 5 pickle files");

    // verify one of the files
    let test_file = format!("{}/0.pkl", temp_path);
    let contents = fs::read(&test_file).expect("failed to read generated file");
    assert!(!contents.is_empty());
    assert_eq!(contents[contents.len() - 1], b'.');
}

#[test]
fn test_cli_batch_mode_with_seed_is_distinct_and_reproducible() {
    let temp_dir1 = TempDir::new().expect("failed to create temp dir 1");
    let temp_dir2 = TempDir::new().expect("failed to create temp dir 2");
    let temp_path1 = temp_dir1.path().to_str().unwrap();
    let temp_path2 = temp_dir2.path().to_str().unwrap();

    cargo_bin_cmd!("pickle-fuzzer")
        .args(["--dir", temp_path1, "--samples", "3", "--seed", "42"])
        .assert()
        .success();

    cargo_bin_cmd!("pickle-fuzzer")
        .args(["--dir", temp_path2, "--samples", "3", "--seed", "42"])
        .assert()
        .success();

    let first_run: Vec<Vec<u8>> = (0..3)
        .map(|idx| fs::read(temp_dir1.path().join(format!("{idx}.pkl"))).unwrap())
        .collect();
    let second_run: Vec<Vec<u8>> = (0..3)
        .map(|idx| fs::read(temp_dir2.path().join(format!("{idx}.pkl"))).unwrap())
        .collect();

    assert_eq!(first_run, second_run);
    assert_ne!(first_run[0], first_run[1]);
    assert_ne!(first_run[1], first_run[2]);
}

